package ru.meguboom.mobile;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class CatalogMetadataTest {
 @Test public void reuploadedBookRetainsPreviousIdentityForProgressMigration()throws Exception{JSONObject b=CatalogMetadata.driveBook(new JSONObject("{id:'new',name:'Book.mp3'}"),new JSONArray("[{id:'drive-old',fileId:'old',name:'Book.mp3',title:'Book'}]"));assertEquals("drive-old",b.getString("legacyId"));}
 @Test public void reuploadedDriveBookKeepsNewIdentityAndFindsMetadata()throws Exception{JSONArray catalog=new JSONArray("[{id:'drive-old',fileId:'old',name:'001. Book.mp3',title:'Book',author:'Author',description:'Synopsis'}]");JSONObject raw=new JSONObject("{id:'new',name:'001. Book.mp3',size:'100'}");JSONObject b=CatalogMetadata.driveBook(raw,catalog);assertEquals("drive-new",b.getString("id"));assertEquals("new",b.getString("fileId"));assertEquals("Author",b.getString("author"));assertEquals("Synopsis",b.getString("description"));assertEquals("book",b.getString("kind"));assertEquals("drive",b.getString("storage"));}
 @Test public void unknownAndAmbiguousDriveFilesAreNotAssignedAnotherBooksDescription()throws Exception{JSONArray catalog=new JSONArray("[{name:'Book.mp3',title:'Book',author:'One',description:'One synopsis'},{name:'Book.mp3',title:'Book',author:'Other',description:'Other synopsis'}]");JSONObject b=CatalogMetadata.driveBook(new JSONObject("{id:'new',name:'Book.mp3'}"),catalog);assertEquals("unassigned",b.getString("kind"));assertFalse(b.has("description"));assertFalse(CatalogMetadata.driveBook(new JSONObject("{id:'song',name:'Song.mp3'}"),catalog).has("description"));}
 @Test public void fillsOldImportedBookDescriptionWithoutChangingIdentity()throws Exception{JSONArray local=new JSONArray("[{id:'local-old',kind:'book',name:'01.Book.mp3',title:'Book',uri:'content://a'}]"),catalog=new JSONArray("[{id:'drive-remote',name:'01.Book.mp3',title:'Book',author:'Author',description:'New synopsis',descriptionType:'excerpt',metadataSource:'https://example.com/book'}]");JSONObject b=CatalogMetadata.refresh(local,catalog).getJSONObject(0);assertEquals("local-old",b.getString("id"));assertEquals("content://a",b.getString("uri"));assertEquals("New synopsis",b.getString("description"));assertEquals("excerpt",b.getString("descriptionType"));}
 @Test public void neverOverwritesMusicOrMatchesTitleWithWrongAuthor()throws Exception{JSONArray local=new JSONArray("[{id:'music',kind:'music',name:'Book.mp3'},{id:'other',kind:'book',title:'Book',author:'Other'}]"),catalog=new JSONArray("[{name:'Book.mp3',title:'Book',author:'Author',description:'Synopsis'}]");JSONArray result=CatalogMetadata.refresh(local,catalog);assertFalse(result.getJSONObject(0).has("description"));assertFalse(result.getJSONObject(1).has("description"));}
 @Test public void actualDriveDatesSurviveCatalogEnrichment()throws Exception{JSONObject raw=new JSONObject().put("id","new-id").put("name","Actual.mp3").put("modifiedTime","2026-11-02T12:00:00Z").put("createdTime","2026-10-01T00:00:00Z");JSONObject b=CatalogMetadata.driveBook(raw,new JSONArray());assertEquals(raw.getString("modifiedTime"),b.getString("modifiedTime"));assertEquals(raw.getString("createdTime"),b.getString("createdTime"));}
}
